css:
* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    font-family:
        Arial,
        Helvetica,
        sans-serif;

    color: #171717;
    background: #ffffff;
}

.hero {
    min-height: 650px;

    color: white;

    background:
        linear-gradient(
            135deg,
            #111111,
            #10A37F
        );
}

.navbar {
    max-width: 1100px;

    margin: auto;

    padding: 25px 20px;

    display: flex;

    justify-content:
        space-between;

    align-items: center;
}

.logo {
    font-size: 20px;
    font-weight: bold;
}

.nav-links {
    display: flex;
    gap: 22px;
}

.nav-links a {
    color: white;
    text-decoration: none;
    font-size: 14px;
}

.hero-content {
    max-width: 900px;

    margin: auto;

    padding:
        110px 20px
        80px;

    text-align: center;
}

.eyebrow {
    color: #10A37F;

    font-size: 13px;

    font-weight: bold;

    text-transform:
        uppercase;

    letter-spacing: 2px;
}

.hero .eyebrow {
    color: #b8ffe9;
}

.hero h1 {
    font-size:
        clamp(
            42px,
            8vw,
            76px
        );

    line-height: 1.05;

    margin:
        20px 0;
}

.hero p {
    font-size: 17px;

    color: #dddddd;

    line-height: 1.7;
}

.primary-button {
    display: inline-block;

    margin-top: 20px;

    padding:
        13px 22px;

    border: none;

    border-radius: 8px;

    background: #10A37F;

    color: white;

    text-decoration: none;

    cursor: pointer;

    font-weight: bold;
}

.section {
    max-width: 1100px;

    margin: auto;

    padding:
        90px 20px;

    text-align: center;
}

.section h2 {
    font-size: 42px;

    margin:
        10px 0 20px;
}

.section > p:not(.eyebrow) {
    max-width: 650px;

    margin:
        auto;

    color: #666;

    line-height: 1.7;
}

.light-section {
    max-width: none;

    background: #f5f7f6;
}

.cards {
    max-width: 1000px;

    margin:
        45px auto 0;

    display: grid;

    grid-template-columns:
        repeat(
            3,
            1fr
        );

    gap: 20px;
}

.card {
    background: white;

    padding: 30px;

    border-radius: 15px;

    box-shadow:
        0 8px 30px
        rgba(
            0,
            0,
            0,
            0.08
        );
}

.card-icon {
    font-size: 28px;

    color: #10A37F;
}

.card h3 {
    margin:
        15px 0 10px;
}

.card p {
    color: #777;

    line-height: 1.6;
}

.contact-section {
    min-height: 400px;
}

footer {
    padding:
        35px 20px;

    text-align: center;

    background: #111111;

    color: white;
}

footer p {
    color: #888;
}

@media (
    max-width: 700px
) {

    .nav-links {
        display: none;
    }

    .hero {
        min-height:
            580px;
    }

    .hero-content {
        padding-top:
            90px;
    }

    .section h2 {
        font-size: 32px;
    }

    .cards {
        grid-template-columns:
            1fr;
    }

}

